          "comment": "Not at best on either outing this year but this C&D suits and current mark is workable",
          "spotlight": "Quirky mare who is usually ridden patiently and must be produced with a well-timed challenge; not at best on either outing this year but is suited by this track (won a division of this race last year) and her current mark is workable if all goes to plan.",
          "quotes": [
            {
              "date": "2024-07-21",
              "horse": "Karannelle",
              "horse_id": "hrs_13683964",
              "race": "Newton Abbot Racecourse Conference Centre Handicap Hurdle (Div I)",
              "race_id": "rac_11324183",
              "course": "Newton Abbot",
              "course_id": "crs_1014",
              "distance_f": "18.5",
              "distance_y": "4070",
              "quote": "Karanelle has been coming down in the weights, which has obviously helped. She is what she is, but the weight has told.  She'll go up and it'll be hard work again, but it was a masterclass ride from James [Bowen]. He was ultra cool and she was up in distance - David Rees, trainer."
            },
            {
              "date": "2019-08-05",
              "horse": "Karannelle",
              "horse_id": "hrs_13683964",
              "race": "Family Fun Raceday Today Mares Maiden Hurdle",
              "race_id": "rac_9584133",
              "course": "Cork",
              "course_id": "crs_15496",
              "distance_f": "16",
              "distance_y": "3520",
              "quote": "She's very small and her jumping needs to improve a bit, she did improve from the first day though. She's a bit inconsistent with her jumping but has a good jump in her, as well as having a great cruising speed. She quickened up well but it was a very moderate mares' race, she's hopefully open to more improvement though. She has form on the Flat over 6f and 7f so when she gets her jumping a bit slicker and sharper she'll be alright - Robbie Power, rider of Karannelle"
            }
          ],
