          "comment": "Made all over C&D in May, his second handicap; raced too freely over 2m5f last time",
          "spotlight": "Made all to open account over C&D (good) in May, his second handicap; raced too freely and was below form when upped to 2m5f here recently but may still have more to offer back at this trip.",
          "quotes": [
            {
              "date": "2025-05-28",
              "horse": "Stinginhisstep",
              "horse_id": "hrs_46729578",
              "race": "Amber Stevens Novices' Limited Handicap Hurdle",
              "race_id": "rac_11624015",
              "course": "Newton Abbot",
              "course_id": "crs_1014",
              "distance_f": "18.5",
              "distance_y": "4070",
              "quote": "What impressed me was how well Springinhisstep stayed, he would be better over a further trip. He's progressive so we hope there's plenty more to come from him. We could tell this week he'd come on from his last race so we knew we had a good chance today. Sean [Houlihan, jockey] said he can't wait to get him over fences - Sue Gardner, trainer."
            }
          ],
