              "distance_f": "7",
              "distance_y": "1554",
              "quote": "We thought a fair bit of Camino Del Ray last year but we never ran him - he's a big horse and took him a while to come to hand. Today was an educational day, they've kicked a long way out and my lad just stays all day. He showed plenty of greenness but it all came good towards the end and he'll improve plenty from that - Ryan Sexton, jockey, speaking to Sky Sports Racing."
