              "distance_f": "6",
              "distance_y": "1320",
              "quote": "Kevin [Manning] said it was a bit of a messy race. They split into two groups and there was no pace on his side. The horse on his outside brought him over to be as one for the last three furlongs but there was nothing to bring him along quick enough. I'm sure he'll be stepped up in class. He's been unlucky to bump into a real good horse first time out and he got mugged at Naas on his outside last time. He deserved today and is a lovely horse for the future for connections. He's got a great attitude and is a beautiful horse to deal with - Ger Flynn, representative for Jim Bolger, trainer of Arranmore"
