          "comment": "C&D winner; form of last week's Hamilton win franked; leading claims and rain won't hurt",
          "spotlight": "C&D winner 12 months ago; dropped down the weights this year and took advantage at Hamilton last week, making all to beat a subsequent winner; 3lb rise still leaves her well handicapped; leading claims with the prospect of rain no concern.",
