          "comment": "Improved efforts on last two starts, including a C&D win, and she's high on the list",
          "spotlight": "Ready win over C&D last month (good to firm) and she backed it up with a solid second of 16 at Ayr 13 days ago (6f, good to soft); on the up and needs taking seriously.",
          "quotes": [],
          "stable_tour": [
            {
              "quote": "We ended up with her because we've got her full brother, Curious Rover, who we've done well with. We picked him up at the sales and got her home and got her going. She's not been the easiest - she is a bit of a madam so it took a good few runs before we got a win on the board, at Redcar in June. I think we've probably got the key to her now though, and her second on her latest start at Ayr was probably a better run than her win. We're looking forward to her next run. She's entered up at Nottingham on Friday and she might also get an entry at Redcar on Sunday and we'll see which one looks the easier. 17-07-25"
            }
          ],
