          "comment": "Bumper winner who was off the mark at Newton Abbot last time; should progress; contender",
          "spotlight": "Fakenham mares' bumper winner in April (2m, good); only third at 4-9 on hurdles debut (didn't seem to stay 2m4f) but better at 2m1f last time when winning mares' novice at Newton Abbot (good to soft), beating her stable companion (had won her two previous two races and was a 2-9 shot) by a neck; contender.",
