          "comment": "Will need to run better than at Uttoxeter when behind two of today's rivals",
          "spotlight": "Good strike-rate over fences and won off 4lb lower last summer; will need to run better than at Uttoxeter when behind two of today's rivals.",
          "quotes": [
            {
              "date": "2023-09-18",
              "horse": "Fringill Dike",
              "horse_id": "hrs_24028739",
              "race": "Make Your Home A Happy Haus Novices' Limited Handicap Chase (GBB Race)",
              "race_id": "rac_11022440",
              "course": "Worcester",
              "course_id": "crs_2626",
              "distance_f": "16.5",
              "distance_y": "3630",
              "quote": "Blinkers have been the making of Fringill Dike. For some reason over hurdles he just lost his confidence a little bit, he didn't like being crowded. The instant we put blinkers on, he was just a different horse. Life is going to get tougher now as his mark is getting towards 130 and the better jumpers will be coming out before too long. There's a race at the first meeting at Wetherby that may suit as long as the ground hasn't gone too slow by then - Jedd O'Keefe, trainer."
            }
          ],
