          "prev_owners": [
            {
              "owner": "Clova Syndicate And Mrs J A Niven",
              "owner_id": "own_1077284",
              "change_date": "2022-09-26"
            }
          ],
          "comment": "An 11yo now but on a good mark and this could be run to suit him",
          "spotlight": "On a good mark but an 11yo now and has lost some of his old zip; ran okay at Uttoxeter last time but got outpaced when it mattered and was never threatening; what will help here is the likelihood of a good pace and some rain; respected.",
          "quotes": [
            {
              "date": "2023-04-22",
              "horse": "Malystic",
              "horse_id": "hrs_16342123",
              "race": "Scotty Brand Handicap Chase (Premier Handicap) (GBB Race)",
              "race_id": "rac_10867077",
              "course": "Ayr",
              "course_id": "crs_78",
              "distance_f": "16.5",
              "distance_y": "3630",
              "quote": "I couldn't explain Cheltenham. Malystic travelled well and he just never picked up, it may have been the ground. Apart from that he's been grand and that's the third big handicap he's won this season. That will be it for this season - Peter Niven, trainer."
            },
            {
              "date": "2023-01-27",
              "horse": "Malystic",
              "horse_id": "hrs_16342123",
              "race": "Sky Bet Extra Places Every Day Handicap Chase (GBB Race)",
              "race_id": "rac_10784137",
              "course": "Doncaster",
              "course_id": "crs_390",
              "distance_f": "16.5",
              "distance_y": "3598",
              "quote": "That was a good performance, particularly with the way Malystic travelled - he was absolutely swinging turning in. He basically missed last season after picking up a terrible infection, so he has low mileage. He's a proper horse, but things haven't gone his way. The only conditions race I was considering was the Game Spirit but it might come a bit quick and then there's the Red Rum at Aintree. I'd love to have a go at the Celebration Chase at the end of the season, but we'll see - Peter Niven, trainer."
            },
            {
              "date": "2022-12-27",
              "horse": "Malystic",
              "horse_id": "hrs_16342123",
              "race": "William Hill Castleford Handicap Chase (GBB Race)",
              "race_id": "rac_10755940",
              "course": "Wetherby",
              "course_id": "crs_2262",
              "distance_f": "15",
              "distance_y": "3336",
              "quote": "Malystic had a hiccup at Cheltenham and he scoped badly afterwards but we got him cleared out and he was in great form. He'd run well first time and this was the right race for him. I hope he's a nice horse - Peter Niven, trainer."
            },
            {
              "date": "2019-02-23",
              "horse": "Malystic",
              "horse_id": "hrs_16342123",
              "race": "Vertem Investing For The Future Standard Open National Hunt Flat Race (All-Weather)",
              "race_id": "rac_9378551",
              "course": "Newcastle (AW)",
              "course_id": "crs_35178",
              "distance_f": "16.5",
              "distance_y": "3576",
              "quote": "Malystic is a nephew of [handicap and Graded winning hurdler] Clever Cookie and is the most like him we've had. He wouldn't have his turn of foot but he's a lovely horse. We'll finish him now or maybe go to Aintree and then he'll go jumping next season - Peter Niven, trainer."
            }
          ],
