          "comment": "Won over fences at Hexham before a 13l defeat back hurdling; rain won't faze him",
          "spotlight": "Not as good as he was but responded well to the new blinkers when beating three rivals over fences at Hexham (1m7f, good) before a 13l defeat over hurdles; has claims and rain won't faze him.",
          "quotes": [
            {
              "date": "2024-11-30",
              "horse": "Glory And Honour",
              "horse_id": "hrs_21212086",
              "race": "Living North Handicap Chase (Go North Monet's Garden Series Qualifier)",
              "race_id": "rac_11443549",
              "course": "Newcastle",
              "course_id": "crs_962",
              "distance_f": "20",
              "distance_y": "4419",
              "quote": "Glory And Honour is a lovely horse and a joy to ride. He needs a really good gallop as he's such a strong traveller and doesn't find as much as you think he would. Today was an ideal scenario and it played into his hands. It was a nice opportunity to get his head back in front - Jonathan England, jockey."
            },
            {
              "date": "2023-12-16",
              "horse": "Glory And Honour",
              "horse_id": "hrs_21212086",
              "race": "bet365 Novices' Limited Handicap Chase (GBB Race)",
              "race_id": "rac_11106381",
              "course": "Doncaster",
              "course_id": "crs_390",
              "distance_f": "19",
              "distance_y": "4211",
              "quote": "I thought Glory And Honour would appreciate the good ground. He was 3lb better off with the favourite so I couldn't see why he started the price he did - Sam England, trainer."
            }
          ],
          "stable_tour": [
            {
              "quote": "He's arguably the best value-for-money horse we've bought. He cost £13,000 and since we purchased him last August he's never been out of the first three and has won £55,000 in prize-money. He's won twice for us, including the big £40k handicap chase at Doncaster in December. He's still running well and he'll go to Cartmel on June 30 for a big £40,000 chase - I think he'll run a big race. 14-06-24"
            }
          ],
