          "comment": "Ran no race last time but a winner the time before and chance if on a going day",
          "spotlight": "Had been chasing (1-3) before beating just two rivals on return to hurdles at Uttoxeter in early June (2m7f, good); ran no race back there three weeks ago but he's better than that and has won on soft.",
          "quotes": [
            {
              "date": "2025-06-05",
              "horse": "Roger Pol",
              "horse_id": "hrs_30016014",
              "race": "Happy 60th Birthday Nigel Kirby Handicap Hurdle",
              "race_id": "rac_11638549",
              "course": "Uttoxeter",
              "course_id": "crs_2184",
              "distance_f": "23.5",
              "distance_y": "5130",
              "quote": "Roger Pol is an absolute dude of a horse. He won a couple of bumpers and was a very good novice hurdler. We went chasing last season with him and he won first time out, but he's not the biggest and he found it a little bit like hard work - Jamie Snowden, trainer, speaking to Sky Sports Racing."
            },
            {
              "date": "2023-03-05",
              "horse": "Roger Pol",
              "horse_id": "hrs_30016014",
              "race": "Get The Best Odds At Oddschecker Open National Hunt Flat Race (Category 1 Elimination) (GBB Race)",
              "race_id": "rac_10821473",
              "course": "Huntingdon",
              "course_id": "crs_676",
              "distance_f": "16",
              "distance_y": "3471",
              "quote": "Roger Pol has won two bumpers now and the plan would be to put him away now for a hurdling campaign in the autumn. He's not very big but makes up in heart what he lacks in stature - Jamie Snowden, trainer."
            },
            {
              "date": "2022-10-19",
              "horse": "Roger Pol",
              "horse_id": "hrs_30016014",
              "race": "Cazoo Open National Hunt Flat Race (Category 1 Elimination) (GBB Race)",
              "race_id": "rac_10679461",
              "course": "Worcester",
              "course_id": "crs_2626",
              "distance_f": "16",
              "distance_y": "3520",
              "quote": "Roger Pol is a lovely horse and we trained his brother Adrrastos who won seven races. What he lacks in size he makes up for in heart and ability. He jumps like an absolute bunny and should have a really nice future - Jamie Snowden, trainer."
            }
          ],
          "stable_tour": [
            {
              "quote": "He won on his chasing debut at Southwell last month when jumping neatly and accurately. He can continue to progress over fences. 06-11-24"
            },
            {
              "quote": "He's lovely, a really cool horse who won two bumpers and was third with a penalty in one as well. He's a cracking jumper and one to look forward to for novice hurdles, but he's far from my only hope in that division. He's got to be exciting. 28-09-23"
            }
          ],
