          "comment": "Led on the line at Cartmel on Saturday; had a hard race and carries a penalty",
          "spotlight": "This new headgear combination worked a treat when leading on the line at Cartmel on Saturday (2m6f, good) with Al Sayah back in third; he did have a hard race and carries a penalty, so worth taking on if turned out again.",
          "quotes": [
            {
              "date": "2023-10-03",
              "horse": "Imperial Data",
              "horse_id": "hrs_33165391",
              "race": "Best Odds Guaranteed Daily With Vickers.Bet Handicap Hurdle (Go North Cab On Target Qualifier)",
              "race_id": "rac_11033178",
              "course": "Sedgefield",
              "course_id": "crs_1482",
              "distance_f": "20",
              "distance_y": "4368",
              "quote": "It (the win) was too late for my liking! It was a learning curve and Imperial Data was getting into the bottom of them a bit when jumping. The track rode beautifully - Ross Chapman, jockey."
            }
          ],
          "stable_tour": [
            {
              "quote": "We've given him a winter holiday as he needs decent ground and he's just coming back now, with a view to probably going novice chasing through the spring and summer. He was progressive after his wind op, which has made a big difference. He was quite an anxious horse before his races, but all that has stopped as I'd imagine he was thinking about his wind before. He's related to Dorans Pride and is a lovely staying chase prospect for John Wade. 24-01-24"
            }
          ],
