          "comment": "In form until a quiet run at Uttoxeter; now visored and capable of having a say",
          "spotlight": "Returned from a break in fine form and now goes in a visor after his disappointing show at Uttoxeter; capable of having a say off this mark and good to soft would be acceptable.",
