          "comment": "Ran well behind Al Sayah last time and a 10lb pull could make it interesting",
          "spotlight": "Not yet won a handicap but one should come his way and scruffy late leaps didn't help when chasing home Al Sayah at Newton Abbot (2m5f, good); a 10lb pull on the winner could make it interesting and he can deal with good and soft ground.",
          "quotes": [],
