          "comment": "In a first-time visor and enjoyed a soft lead when winning in March; not so good since",
          "spotlight": "In a first-time visor and enjoyed a soft lead when winning at Haydock in March (2m5f, good); beaten 13l and 18l since; others preferred.",
          "quotes": [
            {
              "date": "2023-12-26",
              "horse": "Could Be Trouble",
              "horse_id": "hrs_18529770",
              "race": "William Hill Double Your Odds Mares' Handicap Hurdle (Challenger Mares' Hurdle Qualifier)",
              "race_id": "rac_11118913",
              "course": "Aintree",
              "course_id": "crs_832",
              "distance_f": "20",
              "distance_y": "4400",
              "quote": ","
            }
          ],
          "stable_tour": [
            {
              "quote": "It took a few runs to get her head in front when racing in Ireland, but she managed to break her duck at Gowran Park in March. She was bought after that and sent to us and has proved a cracking buy for the lads (Kc Sofas) whose first horse she is. I have nothing but good things to say as she won mares' novice hurdles at Ayr and Uttoxeter before a summer break. She returned at Bangor last month and completed her hat-trick in determined fashion by a half a length. We might look for a mares' race next before going chasing, but I'm keen to get her over fences sooner rather than later as she could be even better over the larger obstacles. 10-11-21"
            }
          ],
