          "owner_id": "own_1333108",
          "prev_trainers": [],
          "prev_owners": [],
          "comment": "Listed winner last year, added Gr 3 on return, steps up to 1m2f, obvious chance",
          "spotlight": "One of two for yard; a Listed winner last season, she added the Group 3 Park Express here (1m, good) on seasonal return; followed that with a fine second behind Porta Fortuna in the Group 2 Lanwades Stud Stakes, also here (1m, good); came up short at Royal Ascot and now steps up to 1m2f for the first time (placed twice at 9.5f); obvious chance.",
          "quotes": [
            {
              "date": "2025-04-12",
              "horse": "One Look",
              "horse_id": "hrs_36528289",
              "race": "Lodge Park Stud Irish EBF Park Express Stakes (Group 3) (Fillies & Mares)",
              "race_id": "rac_11584417",
              "course": "Curragh",
              "course_id": "crs_4628",
              "distance_f": "8",
              "distance_y": "1760",
              "quote": "She's tough and I think a mile is the minimum for now. Ten furlongs will be well within her compass. One Look will have an entry in the Lanwades Stakes. She's a Group winner now and we'll try and go as far up the ladder as we can. The ability was never in question it was just last spring she wasn't ready to do what the world expected her to do. She'll probably prove yet that she is that kind of filly - Paddy Twomey, trainer"
            },
            {
              "date": "2024-03-30",
              "horse": "One Look",
              "horse_id": "hrs_36528289",
              "race": "Irish Stallion Farms EBF Median Auction Race",
              "race_id": "rac_11234431",
              "course": "Cork",
              "course_id": "crs_15496",
              "distance_f": "7",
              "distance_y": "1540",
              "quote": "One Look did what we hoped she would do and it went to plan. I'm thrilled with the way she did it. That's her first piece of work this year. If she goes to Newmarket, she will probably go straight there - Paddy Twomey, trainer"
            },
            {
              "date": "2023-09-23",
              "horse": "One Look",
              "horse_id": "hrs_36528289",
              "race": "Goffs Million",
              "race_id": "rac_11004136",
              "course": "Curragh",
              "course_id": "crs_4628",
              "distance_f": "7",
              "distance_y": "1540",
              "quote": "One Look is a nice filly. I thought I would get her out earlier in the year, but it was just the way things worked out. She was just ready to run this week. I thought she was good enough to be competitive. The plan was to track Frankie (Dettori) on Cherry Blossom and see how we got on. I gave her a Guineas entry this week. It was a big performance to do that and I think that will be it for the year - Paddy Twomey, trainer."
            }
          ],
          "stable_tour": [
            {
              "quote": "She's a lovely filly and I was delighted with her at the Curragh. She only found Porta Fortuna too good there and the Duke of Cambridge has been pencilled in for her. She's smart.  13-06-25"
            }
          ],
