          "comment": "Maiden and Listed winner on easy ground, improved effort latest, rain would aid cause",
          "spotlight": "7f maiden winner on heavy and 1m Listed winner on yielding last term; outclassed in a Group 2 on return (behind One Look) but did better back in Listed company when a 3.5l third at Leopardstown (1m1f, good); a bit to find with some of these but rain would help her cause.",
          "quotes": [
            {
              "date": "2024-10-13",
              "horse": "Azada",
              "horse_id": "hrs_37304099",
              "race": "Irish Stallion Farms EBF Garnet Stakes (Listed Race) (Fillies & Mares)",
              "race_id": "rac_11424660",
              "course": "Naas",
              "course_id": "crs_4992",
              "distance_f": "8",
              "distance_y": "1760",
              "quote": "Azada ran a very good race in the Irish 1,000 Guineas and won well as a two-year-old. The nine and a half furlongs might have been a little too far for her last time at Gowran. She'd been working well and I thought she might be hard to beat today. She's a very big filly and there's a possibility she may be kept in training next year - Dermot Weld, trainer."
            },
            {
              "date": "2023-10-21",
              "horse": "Azada",
              "horse_id": "hrs_37304099",
              "race": "Irish Stallion Farms EBF Fillies Maiden",
              "race_id": "rac_11081889",
              "course": "Leopardstown",
              "course_id": "crs_4862",
              "distance_f": "7",
              "distance_y": "1563",
              "quote": "Azada travelled away and I thought if she showed here what she was showing at home that she would take a lot of beating. When I gave her a little kick she came alive. She is going to be a very nice filly next year - Leigh Roche, rider"
            }
          ],
