          "comment": "Maiden and Listed winner last year on yielding, lacks a run, watch unless ground softens",
          "spotlight": "Second of two for yard; 1m3f maiden winner gained deserved first stakes' win in dominant fashion on her final start of 2024 in a Listed heat at Galway (1m4f, yielding); best form is on ground with an ease and at 1m3f-1m4f; probably best watched on her return unless the ground softens.",
