          "spotlight": "British raider; yard is 6-26 at this venue; won a 1m2f Listed race at Compiegne (soft) on final start in France in October 2023; beaten 11.5l on debut for this stable in the Pretty Polly (1m2f, yld-sft), her only start in 2024; shaped well when a 1.75l second in a Newcastle Group 3 on return last month; interesting, especially if the ground eases.",
