          "prev_owners": [],
          "comment": "Tough and durable course specialist, 12th in Saturday's big sprint handicap",
          "spotlight": "All eight turf wins at this venue (also placed here on ten occasions); as good as ever when landing the Gladness Stakes over C&D in March; a little below his best on next two starts before a fine third in the Greenlands and fourth in a Listed event three weeks ago; only 12th, beaten over ten lengths, in yesterday's big sprint handicap.",
          "quotes": [
            {
              "date": "2025-03-29",
              "horse": "Big Gossey",
              "horse_id": "hrs_20085702",
              "race": "Lester Piggott Gladness Stakes (Listed Race)",
              "race_id": "rac_11588187",
              "course": "Curragh",
              "course_id": "crs_4628",
              "distance_f": "7",
              "distance_y": "1540",
              "quote": "I thought seven furlongs might find Big Gossey out, if it was six furlongs I think he would have won easy. Billy said he was just hanging on desperately. An eight-year-old on that ground against three-year-olds, it doesn't matter how much weight they are giving away, it's very hard for young horses to take on a battle-hardened horse like him. Gary O'Brien, who leads him up, does 90 per cent of the work with him and he just occasionally gives him a pipe opener and lunges him and doesn't have to do much with him. When he arrived in the door, I never thought he'd be doing this! A Gutaifan that couldn't be sold without much of a pedigree. Apparently he might come back here! Today was his 40th start at the track - Charles O'Brien, trainer."
            },
            {
              "date": "2024-11-03",
              "horse": "Big Gossey",
              "horse_id": "hrs_20085702",
              "race": "Cavalor Equine Nutrition Race",
              "race_id": "rac_11450972",
              "course": "Curragh",
              "course_id": "crs_4628",
              "distance_f": "7",
              "distance_y": "1540",
              "quote": "Big Gossey got in well at the conditions and it's a perfect sort of race for him. He is in terrific form and we might find a race for him at Dundalk before next year - Charles O'Brien, trainer."
            },
            {
              "date": "2024-07-20",
              "horse": "Big Gossey",
              "horse_id": "hrs_20085702",
              "race": "David Power Memorial Premier Handicap",
              "race_id": "rac_11342916",
              "course": "Curragh",
              "course_id": "crs_4628",
              "distance_f": "6.5",
              "distance_y": "1383",
              "quote": "Big Gossey has been great for my career. I was delighted to see the rain as he thrives with a bit of an ease. He just loves it here. I would have loved something to bring me a bit further but I wanted to get rolling on him and not let something get first run - Robert Whearty, rider."
            },
            {
              "date": "2023-11-05",
              "horse": "Big Gossey",
              "horse_id": "hrs_20085702",
              "race": "Sheehy Motors Volkswagen Race",
              "race_id": "rac_11097554",
              "course": "Curragh",
              "course_id": "crs_4628",
              "distance_f": "7",
              "distance_y": "1540",
              "quote": "Big Gossey has been a great horse to me this season, he's a legend. He hit the line well when he won the Bold Lad, and over that ground and trip, I didn't think the seven would be a problem - Robert Whearty, rider"
            },
            {
              "date": "2023-09-10",
              "horse": "Big Gossey",
              "horse_id": "hrs_20085702",
              "race": "Irish Stallion Farms EBF \"Bold Lad\" Sprint Handicap (Premier Handicap)",
              "race_id": "rac_11030370",
              "course": "Curragh",
              "course_id": "crs_4628",
              "distance_f": "6",
              "distance_y": "1320",
              "quote": "Big Gossey was a bit unlucky the last day when he missed the break. I travelled into it lovely and got a lovely run up the rail. He had a bit of a look when he got there but he stayed going - Robert Whearty, rider."
            },
            {
              "date": "2022-08-06",
              "horse": "Big Gossey",
              "horse_id": "hrs_20085702",
              "race": "AK Bets \"Higher Limits, Better Prices\" Handicap",
              "race_id": "rac_10640422",
              "course": "Curragh",
              "course_id": "crs_4628",
              "distance_f": "5",
              "distance_y": "1100",
              "quote": "Big Gossey is getting better as the year goes on and he loves it up the Curragh. I'm delighted that he's after getting his head in front today. I always thought six was his ideal trip but a fast run five like that suits him down to the ground - Danny Sheehy, rider."
            },
            {
              "date": "2021-09-12",
              "horse": "Big Gossey",
              "horse_id": "hrs_20085702",
              "race": "Irish Stallion Farms EBF \"Bold Lad\" Sprint Handicap (Premier Handicap)",
              "race_id": "rac_10302435",
              "course": "Curragh",
              "course_id": "crs_4628",
              "distance_f": "6",
              "distance_y": "1320",
              "quote": "Big Gossey travelled throughout and picked up well. I was probably there a bit early but he saw it out. He has plenty of speed and did everything right - Michael Hussey, jockey."
            },
            {
              "date": "2021-02-19",
              "horse": "Big Gossey",
              "horse_id": "hrs_20085702",
              "race": "Join Us On Instagram @dundalk_stadium Handicap",
              "race_id": "rac_10118173",
              "course": "Dundalk (AW)",
              "course_id": "crs_29588",
              "distance_f": "6",
              "distance_y": "1320",
              "quote": "Big Gossey came on from the last run. They went a good strong gallop which suited him and he settled lovely. When I gave him a squeeze he picked up really well. He toughed it out to the line so I'm very happy with him - Danny Sheehy, jockey."
            },
            {
              "date": "2019-12-20",
              "horse": "Big Gossey",
              "horse_id": "hrs_20085702",
              "race": "Irish Stallion Farms EBF Race (Plus 10 Race)",
              "race_id": "rac_9715706",
              "course": "Dundalk (AW)",
              "course_id": "crs_29588",
              "distance_f": "5",
              "distance_y": "1100",
              "quote": "Big Gossey is a horse that's improving every week and there's more improvement in him again. He's an out-and-out sprinter - Mick Hussey, rider"
            }
          ],
