          "prev_owners": [
            {
              "owner": "Anthony Paul Smurfit",
              "owner_id": "own_81588",
              "change_date": "2023-09-08"
            }
          ],
          "comment": "Last year's Jersey Stakes third, landing a 1m Listed event at Leopardstown in May",
          "spotlight": "Progressive at 7f-1m last season; won a 1m Naas handicap off 90; beaten just 1l into third in the 7f Group 3 Jersey Stakes at Royal Ascot; fourth on soft in a Listed race at Tipperary on his final start of 2024; found 6f inadequate at Cork on seasonal debut; appreciated the step up to 1m when landing a Listed event at Leopardstown in May.",
          "quotes": [
            {
              "date": "2025-05-11",
              "horse": "Chicago Critic",
              "horse_id": "hrs_37110857",
              "race": "Porsche In Support Of Breast Cancer Ireland Amethyst Stakes (Listed Race)",
              "race_id": "rac_11633843",
              "course": "Leopardstown",
              "course_id": "crs_4862",
              "distance_f": "8",
              "distance_y": "1760",
              "quote": "Chicago Critic has been up and down in trip, from six furlongs to a mile. I think a mile on fast ground is his ideal trip. They didn't go quick and I had a nice turn of foot towards the end so it's nice to get his head in front again. His best form is over a mile and he feels good at that trip - Ben Coen, jockey."
            },
            {
              "date": "2024-06-22",
              "horse": "Chicago Critic",
              "horse_id": "hrs_37110857",
              "race": "Jersey Stakes (Group 3)",
              "race_id": "rac_11299548",
              "course": "Ascot",
              "course_id": "crs_52",
              "distance_f": "7",
              "distance_y": "1540",
              "quote": "We're absolutely delighted - that was fantastic. We came over because we thought we had a nice horse on our hands, but when you look at the strength of the race, it was a very, very good race and Chicago Critic ran his heart out. Ben gave him a great ride. We got excited up there for a couple of seconds - we thought he was coming, but he just couldn't get there. No fault of the horse, he ran brilliantly. Today was the plan, and now we know we have a horse of this level, we will think about what's next. He'll stay at seven or a mile - I think he'll get a mile no problem - Johnny Murtagh, trainer."
            },
            {
              "date": "2024-05-19",
              "horse": "Chicago Critic",
              "horse_id": "hrs_37110857",
              "race": "Royal Ascot Trials At Naas Handicap",
              "race_id": "rac_11291189",
              "course": "Naas",
              "course_id": "crs_4992",
              "distance_f": "8",
              "distance_y": "1760",
              "quote": "Chicago Critic has been gelded since his last run so maybe that and the good ground both helped. I'm delighted with that and he could be a horse to go to Ascot for the Britannia Handicap - Johnny Murtagh, trainer"
            },
            {
              "date": "2023-10-14",
              "horse": "Chicago Critic",
              "horse_id": "hrs_37110857",
              "race": "Irish Stallion Farms EBF Maiden",
              "race_id": "rac_11071879",
              "course": "Naas",
              "course_id": "crs_4992",
              "distance_f": "8",
              "distance_y": "1760",
              "quote": "Ben (Coen, jockey) said Chicago Critic is very professional, very genuine and should get a mile and a quarter next year - Johnny Murtagh, trainer."
            }
          ],
