          "comment": "Second to Poet Master in this race last season, hard to make a case for him on recent form",
          "spotlight": "Has gained two of his seven wins at this venue and was second to Poet Master in this race last season; best performance this term when defeating Mutasarref in a 1m Listed race at Leopardstown in April; below since then, including in a race won by Chicago Critic; last of four when 25-1 outsider at Leopardstown on Thursday.",
          "quotes": [
            {
              "date": "2023-08-17",
              "horse": "Lord Massusus",
              "horse_id": "hrs_31451700",
              "race": "Bahrain Turf Club Desmond Stakes (Group 3)",
              "race_id": "rac_11004058",
              "course": "Leopardstown",
              "course_id": "crs_4862",
              "distance_f": "8",
              "distance_y": "1760",
              "quote": "Lord Massusus disappointed last day but things didn't go right. We got him switched off today and he came home like a good horse. It was a good performance - Joe Murphy, trainer."
            },
            {
              "date": "2023-05-06",
              "horse": "Lord Massusus",
              "horse_id": "hrs_31451700",
              "race": "The Dillon Marshall Property Consultants Handicap (Premier Handicap)",
              "race_id": "rac_10922834",
              "course": "Naas",
              "course_id": "crs_4992",
              "distance_f": "6",
              "distance_y": "1305",
              "quote": "We'll make an entry for the Jersey Stakes now, seven furlongs would be ideal - Joe Murphy, trainer of Lord Massusus"
            },
            {
              "date": "2022-09-25",
              "horse": "Lord Massusus",
              "horse_id": "hrs_31451700",
              "race": "Irish EBF Auction Series Race (IRE Incentive Race)",
              "race_id": "rac_10687807",
              "course": "Curragh",
              "course_id": "crs_4628",
              "distance_f": "6",
              "distance_y": "1320",
              "quote": "Lord Massusus put up a very good performance and I think he's a good horse. That qualifies him for the final at Naas next month. He did what good horses do today - Joe Murphy, trainer."
            },
            {
              "date": "2022-09-20",
              "horse": "Lord Massusus",
              "horse_id": "hrs_31451700",
              "race": "Irish Stallion Farms EBF Premier Nursery Handicap (Premier Handicap)",
              "race_id": "rac_10684739",
              "course": "Listowel",
              "course_id": "crs_4940",
              "distance_f": "8",
              "distance_y": "1760",
              "quote": "Lord Massusus was very straightforward and travelled well. He's plenty green, around here it's a tight enough track, but when I squeezed him he picked up and when he hit the front he pricked his ears and won with a little left. Hopefully he'll keep improving, he got the trip well. He's got a bit of scope and will make a nice three-year-old - Gary Carroll, jockey."
            }
          ],
