          "comment": "Placed behind Lord Massusus and Chicago Critic this term, not at his best on latest",
          "spotlight": "Winner of 10 of his 25 races, including twice at Group 3 level at Leopardstown last year, when form also featured a Group 2 second behind Diego Velazquez; placed behind Lord Massusus and Chicago Critic in 1m Listed events this season, below best in a 7f Group 3 last time, and needs to reverse form with Easy and East Hampton.",
          "quotes": [
            {
              "date": "2024-08-08",
              "horse": "Mutasarref",
              "horse_id": "hrs_25376106",
              "race": "Bahrain Turf Club Desmond Stakes (Group 3)",
              "race_id": "rac_11352081",
              "course": "Leopardstown",
              "course_id": "crs_4862",
              "distance_f": "8",
              "distance_y": "1760",
              "quote": "You don't expect to be winning these races with the penalties. We were a bit disappointed with Mutasarref last time at the Curragh, but that's the Curragh. I don't think he's ever run his best race there but he does it here. You think the penalties are going to stop him and he just keeps doing things like that. Horses like him make you enjoy the game. The plan is to come back here on Champions Weekend for the Group 2 Boomerang Stakes, which is beyond him, but it will give us another day out - Ger Lyons, trainer."
            },
            {
              "date": "2024-05-19",
              "horse": "Mutasarref",
              "horse_id": "hrs_25376106",
              "race": "Owenstown Stud Stakes (Listed Race)",
              "race_id": "rac_11291163",
              "course": "Naas",
              "course_id": "crs_4992",
              "distance_f": "7",
              "distance_y": "1540",
              "quote": "Mutasarref came back from an injury and as Colin said he's back to himself. That's his grade and seven furlongs is his trip. A mile is just a tad beyond him - Ger Lyons, trainer."
            },
            {
              "date": "2023-10-22",
              "horse": "Mutasarref",
              "horse_id": "hrs_25376106",
              "race": "Bahrain Turf Club Knockaire Stakes (Listed Race)",
              "race_id": "rac_11081798",
              "course": "Leopardstown",
              "course_id": "crs_4862",
              "distance_f": "8",
              "distance_y": "1760",
              "quote": "Mutasarref has been on the wane all year but the ground here helped his old injuries and his old bones. He has been a very lucky horse for us and on his day he is still a good horse - Ger Lyons, trainer."
            },
            {
              "date": "2022-06-24",
              "horse": "Mutasarref",
              "horse_id": "hrs_25376106",
              "race": "Hollywoodbets We're Painting Ireland Purple Handicap",
              "race_id": "rac_10603047",
              "course": "Curragh",
              "course_id": "crs_4628",
              "distance_f": "7",
              "distance_y": "1540",
              "quote": "Mutasarref is a stakes horse in a handicap. I don't know if he's a Group 3 but he's definitely a Listed. We'll go to Champions Weekend with him now - Ger Lyons, trainer."
            },
            {
              "date": "2021-09-21",
              "horse": "Mutasarref",
              "horse_id": "hrs_25376106",
              "race": "Jet & Peggy O'Carroll Memorial (C & G) Maiden",
              "race_id": "rac_10321103",
              "course": "Listowel",
              "course_id": "crs_4940",
              "distance_f": "7",
              "distance_y": "1540",
              "quote": "Mutasarref looked like he should go and win today. We'll look for a handicap for him. We thought he would handle the ground well and he did - Kris Weld, assistant trainer."
            }
          ],
