          "comment": "Beaten 2 1/2l in fifth behind Vespertilio here three weeks ago, also held by Easy",
          "spotlight": "Won a 6f course maiden last season, returned with a 7f handicap success on testing ground at Naas; has run creditably since raised in class, but has a bit to find with Easy on Leopardstown running and was beaten 2 1/2l in fifth behind Vespertilio here three weeks ago.",
          "quotes": [
            {
              "date": "2025-03-23",
              "horse": "East Hampton",
              "horse_id": "hrs_41534864",
              "race": "Irish Racing Writers Association Ron McKnight Memorial Madrid Handicap",
              "race_id": "rac_11583026",
              "course": "Naas",
              "course_id": "crs_4992",
              "distance_f": "7",
              "distance_y": "1540",
              "quote": "The only time East Hampton encountered ground that resembled soft, he won on it. We brought him to Dundalk the last day but he didn't like the surface so we put him away for this. Obviously six furlongs was as far as he'd gone so the trip was a worry but I was delighted to see the low draw. Luke gave him a fabulous ride, dropped him in and switched him off as much as he could. He will learn from it, he was fresh today. He saw it out well, though and didn't stop galloping. As long as the ground has an ease, we'll keep going - David Marnane, trainer."
            }
          ],
