              "distance_f": "5",
              "distance_y": "1100",
              "quote": "I thought Mymomentintime couldn't get beaten last time at Cork and I don't know what happened, maybe he didn't stay six furlongs. He was as dead as a maggot and we got him blood tested but we just don't know what happened - it was one of those things. I thought he'd do this three races ago but sometimes with sprinters they take a while to get the hang of things. He'll make a lovely horse next year because he's a big, strong type. He's maturing all the time - Susan Finn, trainer."
